(()=>{document.documentElement.classList.add('js');const blocks=document.querySelectorAll('[data-reveal]');const show=(el)=>el.classList.add('is-shown');if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const io=new IntersectionObserver((entries)=>entries.forEach((entry)=>{if(entry.isIntersecting){show(entry.target);io.unobserve(entry.target);}}),{threshold:0.12,rootMargin:'0px 0px -40px 0px'});blocks.forEach((el)=>io.observe(el));}else{blocks.forEach(show);}
document.addEventListener('focusin',(e)=>{const b=e.target.closest('[data-reveal]');if(b)show(b);});const form=document.getElementById('contactForm');const status=document.getElementById('contactStatus');const fields=[{input:document.getElementById('contactName'),error:document.getElementById('contactNameError'),valid:(v)=>v.trim().length>0},{input:document.getElementById('contactEmail'),error:document.getElementById('contactEmailError'),valid:(v)=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())},];const check=(f)=>{const ok=f.valid(f.input.value);f.input.setAttribute('aria-invalid',String(!ok));f.error.hidden=ok;if(ok)f.input.removeAttribute('aria-describedby');else f.input.setAttribute('aria-describedby',f.error.id);return ok;};fields.forEach((f)=>f.input.addEventListener('blur',()=>{if(f.input.value)check(f);}));form.addEventListener('submit',(event)=>{event.preventDefault();const results=fields.map(check);const first=fields[results.indexOf(false)];if(first){first.input.focus();status.textContent='Check the marked fields.';return;}
status.textContent='Thank you. This review demo does not send enquiries yet. Contact integration is planned.';});window.ctuavSelectProduct=(line)=>{const select=document.getElementById('contactProduct');if(!line){select.value='';return;}
const option=[...select.options].find((o)=>o.text===line);if(option)select.value=option.value||option.text;};addEventListener('message',(event)=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo'||event.data.type!=='contact-product')return;window.ctuavSelectProduct(event.data.line);});})();addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo'||event.data.type!=='palette')return;const theme=event.data.theme;document.documentElement.dataset.theme=theme;document.body.dataset.theme=theme;document.querySelectorAll('.palette-button').forEach(button=>{button.classList.toggle('selected',button.dataset.palette===theme);button.setAttribute('aria-pressed',String(button.dataset.palette===theme));});});addEventListener('message',event=>{if(event.source===parent&&event.data?.namespace==='ctuav-demo'&&event.data.type==='view-active'&&event.data.active)scrollTo({top:0,behavior:'instant'});});"use strict";(()=>{document.querySelectorAll('[data-footer-route]').forEach((button)=>button.addEventListener('click',()=>{const route=button.dataset.footerRoute;if(window.ctuavDemo)window.ctuavDemo.navigate(route);else if(parent!==window)parent.postMessage({namespace:'ctuav-demo',type:'route',route},'*');}));})();